from __future__ import absolute_import
import re
import time
from selenium.common.exceptions import NoSuchElementException
from selenium.webdriver import ActionChains
from selenium.webdriver.common.by import By
from selenium.webdriver.common.keys import Keys
from taf.ul.oam.selenium_core.common import PagePart, BasicPage
from .exceptions import *


class PageCommonMethod(BasicPage):

    def __init__(self, driver):
        super(PageCommonMethod, self).__init__(driver)

    def select_element(self, elem_xpath, enable=True):
        element = self._driver.find_element_by_xpath(elem_xpath)
        if element.is_selected() != enable:
            element.click()

    def write_value(self, elem_xpath, value):
        element = self._driver.find_element_by_xpath(elem_xpath)
        element.send_keys(Keys.CONTROL, 'a')
        element.send_keys(str(value))

    def write_value_and_enter(self, elem_xpath, value):
        element = self._driver.find_element_by_xpath(elem_xpath)
        element.send_keys(Keys.CONTROL, 'a')
        element.send_keys(str(value))
        element.send_keys(Keys.ENTER)

    def click_element(self, elem_xpath):
        self._driver.find_element_by_xpath(elem_xpath).click()

    def expand_tree_by_elem_xpath(self, layer_xpath, interval_seconds=1):
        tree_elem_xpaths = self._deduce_tree_xpaths(layer_xpath)
        self.expand_element_tree_by_xpath_list(tree_elem_xpaths, interval_seconds)

    def expand_element_tree_by_xpath_list(self, elem_xpath_list, interval_seconds=1):
        for elem_xpath in elem_xpath_list:
            time.sleep(interval_seconds)
            if self._is_tree_folder(elem_xpath) and self._is_element_expanded(elem_xpath):
                continue
            self.click_element(self._get_collapsed_element_xpath(elem_xpath))

    def _is_tree_folder(self, elem_xpath):
        return True if 'collapsed' in elem_xpath or 'expanded' in elem_xpath else False

    def _is_element_expanded(self, elem_xpath):
        expanded_elem_xpath = self._get_expanded_element_xpath(elem_xpath)
        expanded_elem = self._driver.find_element_by_xpath(expanded_elem_xpath)
        return expanded_elem.is_displayed()

    def _get_expanded_element_xpath(self, elem_xpath):
        return elem_xpath.replace('collapsed', 'expanded')

    def _get_collapsed_element_xpath(self, elem_xpath):
        return elem_xpath.replace('expanded', 'collapsed')

    def _deduce_tree_xpaths(self, elem_xpath):
        layer_names = self._find_tree_xpath_layers(elem_xpath)
        header, tail = self._get_tree_xpath_header_and_tail(elem_xpath)
        expanded_tail = 'Node:handle:img:expanded"]'
        tree_elem_xpaths = []
        for layer_no in range(1, len(layer_names) + 1):
            elem_tail = tail if layer_no == len(layer_names) else expanded_tail
            tree_elem_xpaths.append(self._join_tree_elem_xpath(header, layer_names[:layer_no], elem_tail))
        return tree_elem_xpaths

    def _join_tree_elem_xpath(self, header, layer_names, tail):
        return header + ':' + ':'.join(layer_names) + '::' + tail

    def _find_tree_xpath_layers(self, elem_xpath):
        return re.findall('j__id\d+:\d+', elem_xpath)

    def _get_tree_xpath_header_and_tail(self, elem_xpath):
        header = elem_xpath.split(':j__id')[0]
        tail = elem_xpath.split('::')[-1]
        return (header, tail)

    def get_elem_text(self, elem_xpath):
        """
        get element text value
        :param elem_xpath: element xpath
        """
        return self._driver.find_element_by_xpath(elem_xpath).text

    def get_element_attribute(self, elem_xpath, attr_name):
        elem = self._driver.find_element_by_xpath(elem_xpath)
        return elem.get_attribute(attr_name)

    def move_to_element(self, elem_xpath):
        elem = self._driver.find_element_by_xpath(elem_xpath)
        ActionChains(self._driver).move_to_element(elem).perform()

    def scroll_element_to_view(self, elem_xpath):
        self.wait_for_visibility((By.XPATH, elem_xpath))
        elem = self._driver.find_element_by_xpath(elem_xpath)
        if not elem.is_displayed():
            self._driver.execute_script("arguments[0].scrollIntoView();", elem)
            self.wait_for_visibility((By.XPATH, elem_xpath))
        return elem


class TabBar(PagePart):

    def __init__(self, driver):
        super(TabBar, self).__init__(driver)

    def click_tab(self, id):
        """
        Click tab with given id

        :param id: tab id
        """
        self._wait_for_element_by((By.ID, id))
        li = self._driver.find_element_by_id(id)
        a = li.find_element_by_tag_name("a")
        a.click()

    def click_tab_by_xpath(self, xpath):
        """
        Click tab with given xpath

        :param xpath: tab xpath
        """
        self._wait_for_element_by((By.XPATH, xpath))
        self._driver.find_element_by_xpath(xpath).click()


class SoftwareManagerTabbar(TabBar):

    _NETWORK_STATUS_XPATH = "//span[text()='Network Status']/.."
    _NETWORK_OPERATIONS_XPATH = "//span[text()='Network Operations']/.."
    _SCHEDULES_XPATH = "//span[text()='Schedules']/.."
    _SOFTWARE_ARCHIVE_XPATH = "//span[text()='Software Archive']/.."
    _BACKUP_ARCHIVE_XPATH = "//span[text()='Backup Archive']/.."
    _PREFERENCES_XPATH = "//span[text()='Preferences']/.."

    def __init__(self, driver):
        super(SoftwareManagerTabbar, self).__init__(driver)

    def click_network_status(self):
        self.click_tab_by_xpath(self._NETWORK_STATUS_XPATH)

    def click_network_operations(self):
        self.click_tab_by_xpath(self._NETWORK_OPERATIONS_XPATH)

    def click_schedules(self):
        self.click_tab_by_xpath(self._SCHEDULES_XPATH)

    def click_software_archive(self):
        self.click_tab_by_xpath(self._SOFTWARE_ARCHIVE_XPATH)

    def click_backup_archive(self):
        self.click_tab_by_xpath(self._BACKUP_ARCHIVE_XPATH)

    def click_preferences(self):
        self.click_tab_by_xpath(self._PREFERENCES_XPATH)


class LoginPage(BasicPage):
    def __init__(self, driver):
        super(LoginPage, self).__init__(driver)

    def insert_login(self, login):
        """
        Inserts given login to login field

        :param login: user login
        """
        self.insert_text_to_field("login:username", login)

    def insert_password(self, password):
        """
        Inserts given password to password field

        :param password: user password
        """
        self.insert_text_to_field("login:password", password)

    def click_login_button(self):
        """
        Clicks login button
        """
        elem = self._driver.find_element_by_id("login:loginButton")
        elem.click()

    def click_accept_button(self):
        self.wait_for_visibility((By.ID, "login:legalPanelCloseButton"))
        elem = self._driver.find_element_by_id("login:legalPanelCloseButton")
        elem.click()

    def login(self, username, password, after_reset=False):
        """
        Perform user login with given credentials. If site returns warning about
        incompatible browser click proceed link.

        :param username:
        :param password:
        :param after_reset: allow login to fail. New vesions of software performs login automatically.
        :return: HomePage object
        """
        try:
            self.insert_login(username)
            self.insert_password(password)
            self.click_login_button()
            self.click_accept_button()
        except NoSuchElementException:
            if not after_reset:
                raise
        return HomePage(self._driver)


class HomePage(PageCommonMethod, TabBar):
    _LOGOFF_XPATH = '//*[@id="logoff"]'
    _LOGOFF_BUTTON_XPATH = '//*[@id="logoutButton"]'

    _HOME_XPATH = "//*[contains(@ng-click,'Home')]"
    _CONFIGURATION_XPATH = "//a[contains( @ folder, 'configuration')]"
    _CONFIGURATION_CM_OPERATIONS_MANAGER_XPATH = "//a[contains(@href,'racpmc')]"

    def __init__(self, driver):
        super(HomePage, self).__init__(driver)

    def click_home(self):
        try:
            self._driver.find_element_by_xpath(self._HOME_XPATH).click()
        except NoSuchElementException:
            pass

    def click_configuration(self):
        self.click_home()
        self.click_element(self._CONFIGURATION_XPATH)

    def click_configuration_cm_operations_manager(self):
        self.click_configuration()
        self.click_element(self._CONFIGURATION_CM_OPERATIONS_MANAGER_XPATH)

    def logout(self):
        self._driver.find_element_by_xpath(self._LOGOFF_XPATH).click()
        self.wait_for_visibility((By.XPATH, self._LOGOFF_BUTTON_XPATH))
        self._driver.find_element_by_xpath(self._LOGOFF_BUTTON_XPATH).click()


class SoftwareManagerPage(PageCommonMethod, SoftwareManagerTabbar):
    def __init__(self, driver):
        super(SoftwareManagerPage, self).__init__(driver)


class CommonPage(PageCommonMethod, PagePart):
    def __init__(self, driver):
        super(CommonPage, self).__init__(driver)
